<script setup>
import { computed, ref, onMounted, onBeforeUnmount } from 'vue';
import { useForm } from '@inertiajs/vue3';
const props=defineProps({item:{type:Object,required:true},requirements:{type:Object,default:()=>({})}});
const emit=defineEmits(['close']);
const dialog=ref(null), documentIndex=ref(0), reviewed=ref(false), imageFailed=ref(false);
const titles={spaces:'Aadi Properties',haul:'Aadi UV',raketeer:'Aadi Raket'};
const labels={applicantType:'Applicant type',businessName:'Registered business',relationship:'Ownership / authority',serviceCategory:'Service category',skills:'Skills and qualifications',experienceYears:'Years of experience'};
const application=computed(()=>props.item.application);
const documents=computed(()=>application.value?.documents||[]);
const document=computed(()=>documents.value[documentIndex.value]);
const missing=computed(()=>Object.entries(props.requirements).filter(([type,rule])=>rule.required&&!documents.value.some(doc=>doc.type===type)));
const form=useForm({version:application.value?.version||null,status:application.value && !missing.value.length?'approved':'rejected',reviewNote:''});
const date=value=>value?new Date(value).toLocaleString('en-PH'):'Not provided';
let overflow, opener;
onMounted(()=>{opener=window.document.activeElement;overflow=window.document.body.style.overflow;window.document.body.style.overflow='hidden';dialog.value.showModal();});
onBeforeUnmount(()=>{dialog.value?.close();window.document.body.style.overflow=overflow;opener?.focus?.();});
function close(){if(!form.processing)dialog.value.close();}
function submit(){if(form.processing)return;if(form.status==='approved'&&(!reviewed.value||!application.value||missing.value.length))return;form.post(`/admin/approvals/${props.item.userId}/${props.item.service}`,{preserveScroll:true,onSuccess:()=>emit('close')});}
</script>
<template><Teleport to="body"><dialog ref="dialog" class="verification-dialog" aria-labelledby="verification-title" @close="emit('close')" @cancel="form.processing && $event.preventDefault()">
<header><div><p>{{ titles[item.service] }} · Provider verification</p><h2 id="verification-title">{{ application?.displayName || item.name }}</h2><span class="pending">Pending review</span></div><button type="button" aria-label="Close application review" :disabled="form.processing" autofocus @click="close">×</button></header>
<div class="review-grid"><section class="application-details"><h3>Applicant</h3><dl><dt>Account holder</dt><dd>{{ item.name }}</dd><dt>Email</dt><dd>{{ item.email }}</dd><template v-if="application"><dt>Phone</dt><dd>{{ application.phone }}</dd><dt>Area</dt><dd>{{ application.area }}</dd><dt>Submitted</dt><dd>{{ date(application.submittedAt) }}</dd><dt>Application ID</dt><dd>{{ application.id }}</dd></template></dl>
<template v-if="application"><h3>Provider information</h3><p class="description">{{ application.description }}</p><dl><template v-for="(label,key) in labels" :key="key"><template v-if="application.details?.[key] != null && application.details[key] !== ''"><dt>{{ label }}</dt><dd>{{ application.details[key] }}</dd></template></template></dl></template>
<p v-else class="notice">This older request has no application details or documents. Request an update before approving.</p>
<h3>Document checklist</h3><ul class="checklist"><li v-for="(rule,type) in requirements" :key="type"><span>{{ rule.label }}</span><strong :class="{missing:rule.required&&!documents.some(doc=>doc.type===type)}">{{ documents.some(doc=>doc.type===type)?'Provided':rule.required?'Missing required':'Optional' }}</strong></li></ul><p class="muted">“Provided” confirms an upload exists in the application. Check its contents, validity and relevance before approving.</p>
</section><section class="document-review"><h3>Submitted documents <span>({{ documents.length }})</span></h3><label v-if="documents.length">Choose document<select v-model="documentIndex" @change="imageFailed=false"><option v-for="(doc,index) in documents" :key="doc.index" :value="index">{{ requirements[doc.type]?.label||'Supporting document' }} — {{ doc.name }}</option></select></label>
<template v-if="document"><div class="document-meta"><strong>{{ document.name }}</strong><p v-if="document.reference">Reference: {{ document.reference }}</p><p v-if="document.expiresAt">Expires: {{ document.expiresAt }}</p><a :href="document.url" target="_blank" rel="noopener">Download original ↗</a></div><div class="document-preview"><img v-if="/\.(jpe?g|png|webp)$/i.test(document.name)&&!imageFailed" :key="document.url" :src="document.url+'?preview=1'" :alt="document.name" @error="imageFailed=true"/><iframe v-else-if="/\.pdf$/i.test(document.name)" :key="document.url" :src="document.url+'?preview=1'" :title="'Document preview: '+document.name"/><p v-else>Preview unavailable. Download the original document to review it.</p></div><p class="muted">If your browser cannot display this document, use Download original.</p></template><p v-else class="notice">No supporting documents were submitted.</p>
</section></div>
<form class="decision" @submit.prevent="submit"><h3>Review decision</h3><p class="muted">Approval grants this role only. It does not verify every listing or replace email verification.</p><div class="decision-fields"><label>Decision<select aria-label="Decision" v-model="form.status" :disabled="form.processing"><option value="approved" :disabled="!application||missing.length>0">Approve provider role</option><option value="rejected">Request an update</option></select></label><label>Review note {{ form.status==='rejected'?'(required)':'(optional)' }}<textarea v-model="form.reviewNote" :required="form.status==='rejected'" :disabled="form.processing" maxlength="2000" rows="3" placeholder="Explain missing, unclear or expired documents so the applicant can correct them."/></label></div><label v-if="form.status==='approved'" class="acknowledge"><input v-model="reviewed" type="checkbox" required :disabled="form.processing"/>I have reviewed the application and supporting documents.</label><p v-if="missing.length" class="error">Required documents are missing. Request an update to proceed.</p><p v-for="(error,key) in form.errors" :key="key" class="error" role="alert">{{ error }}</p><footer><button type="button" class="secondary" :disabled="form.processing" @click="close">Cancel</button><button type="submit" class="primary" :disabled="form.processing || (form.status==='approved' && (!reviewed||!application||missing.length>0))">{{ form.processing?'Saving…':form.status==='approved'?'Confirm approval':'Send update request' }}</button></footer></form>
</dialog></Teleport></template>
<style scoped>
.verification-dialog{margin:auto;width:min(1120px,calc(100% - 32px));max-height:calc(100dvh - 32px);overflow:auto;overscroll-behavior:contain;border:0;border-radius:18px;padding:0;background:white;color:#183e3b;font-family:Quicksand,system-ui,sans-serif}.verification-dialog::backdrop{background:#082c2999}.verification-dialog header{display:flex;justify-content:space-between;gap:20px;padding:24px;border-bottom:1px solid #dce7e4}.verification-dialog header p{font-size:12px;color:#637b76;margin-bottom:6px}.verification-dialog h2{font-size:25px;font-weight:700;overflow-wrap:anywhere}.verification-dialog header button{width:44px;height:44px;font-size:28px;flex:none}.pending{display:inline-block;background:#fff3bf;color:#79540a;padding:5px 10px;border-radius:8px;font-size:12px;margin-top:10px}.review-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr)}.review-grid>section{min-width:0;padding:24px}.document-review{background:#f4f8f6;border-left:1px solid #dce7e4}.verification-dialog h3{font-weight:700;font-size:17px;margin-bottom:14px}.verification-dialog dl{display:grid;grid-template-columns:130px minmax(0,1fr);gap:8px 16px;font-size:13px;margin:16px 0 28px}.verification-dialog dt{color:#637b76}.verification-dialog dd,.description{overflow-wrap:anywhere;white-space:pre-wrap}.verification-dialog p{font-size:13px;line-height:1.6}.checklist{list-style:none;margin:0;padding:0}.checklist li{display:flex;gap:12px;justify-content:space-between;padding:10px 0;border-bottom:1px solid #dce7e4;font-size:12px}.checklist strong{white-space:nowrap;color:#137671}.checklist .missing,.error{color:#b42318}.muted{color:#637b76;margin-top:12px}.verification-dialog label{display:grid;gap:8px;font-size:13px}.verification-dialog select,.verification-dialog textarea{width:100%;max-width:100%;min-height:44px;border:1px solid #b7d8d0;background:white;border-radius:9px;padding:10px;color:#183e3b}.document-meta{font-size:13px;margin:16px 0;overflow-wrap:anywhere}.document-meta a{display:inline-flex;align-items:center;min-height:44px;color:#137671;text-decoration:underline}.document-preview{background:#e5eeeb;border:1px solid #dce7e4;border-radius:10px;overflow:hidden}.document-preview img{display:block;width:100%;max-height:520px;object-fit:contain}.document-preview iframe{display:block;width:100%;height:460px;border:0}.document-preview p,.notice{padding:16px}.notice{background:#fff3bf;border-radius:10px}.decision{padding:24px;border-top:1px solid #dce7e4}.decision-fields{display:grid;grid-template-columns:240px minmax(0,1fr);gap:20px;margin-top:16px}.acknowledge{display:flex!important;align-items:flex-start;gap:10px;margin-top:16px}.acknowledge input{width:18px;height:18px;margin-top:2px;flex:none;accent-color:#137671}.verification-dialog footer{display:flex;justify-content:flex-end;gap:12px;margin-top:20px}.primary,.secondary{min-height:44px;border:1px solid #137671;border-radius:10px;padding:10px 16px;font-size:13px;font-weight:700}.primary{background:#137671;color:white}.secondary{background:white;color:#137671}.verification-dialog button:disabled{opacity:.5;cursor:not-allowed}.verification-dialog :is(button,a,input,select,textarea):focus-visible{outline:3px solid #e6bb51;outline-offset:3px}@media(max-width:700px){.review-grid,.decision-fields{grid-template-columns:1fr}.document-review{border-left:0;border-top:1px solid #dce7e4}.verification-dialog{width:calc(100% - 16px);max-height:calc(100dvh - 16px)}.verification-dialog header,.review-grid>section,.decision{padding:18px}.verification-dialog dl{grid-template-columns:1fr;gap:4px}.verification-dialog dd{margin-bottom:10px}.verification-dialog h2{font-size:21px}.document-preview iframe{height:360px}}
</style>
